\begin{lemma}
\label{lemma-monoidal-unit-unique}
Let $(\mathcal{C}, \otimes, \phi)$ be as above.
Let $(\mathbf{1}, 1)$ be a unit (see Lemma \ref{lemma-monoidal-unit}).
Then
\begin{enumerate}
\item $1 \otimes \text{id}_\mathbf{1} = \text{id}_\mathbf{1} \otimes 1$
\item $\Gamma = \text{Mor}(\mathbf{1}, \mathbf{1})$ is a commutative monoid,
\item  $a = 1 \circ (a \otimes \text{id}_\mathbf{1}) \circ 1^{-1} =
1 \circ (\text{id}_\mathbf{1} \otimes a) \circ 1^{-1}$ for all $a \in \Gamma$,
\item any other unit is isomorphic to $(\mathbf{1}, 1)$
by a unique isomorphism.
\end{enumerate}
\end{lemma}

